      rule('z.row-amount', 'items/amount', 'Compute', { if: [{ var: 'row.enabled' }, 1, null] }, 'Row'),
    ], { rowKeys: ['row.amount'], items: [{ _id: 'r1', enabled: true }] }).first
    expect(first.values.get('row:items/r1/missing')).toEqual({ state: 'Resolved', value: [] })
