  })

  it('atomically refuses cumulative non-ascii byte growth while preserving the prior graph', () => {
    const prefix = '{"a":1,"payload":"'
    const source = `${prefix}${'é'.repeat((INPUT_MAX_UTF8_BYTES - prefix.length - 2) / 2)}"}`
